import { registerWebComponents } from '@domg-wc/common';
import { VlTableComponent } from '@domg-wc/components/block';

registerWebComponents([VlTableComponent]);

components-block-table--table-expandable.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlTableComponent } from '@domg-wc/components/block';

// VlTableComponent registreert ook vl-button.
registerWebComponents([VlTableComponent]);

const table = document.querySelector('#vl-table-with-custom-expandable-details');

// Door de cel met data-with-expand-details voegt vl-table op die rij geen eigen knop toe. toggleDetails() klapt
// alle rijen met data-details-id="details-row1" open of dicht. Voor details-row2 en details-row3 voegt vl-table
// wel zelf een knop toe.
table.querySelector('td[data-with-expand-details] vl-button').addEventListener('click', () => {
    table.toggleDetails('details-row1');
});
